// DO NOT EDIT THIS FILE.
// These tests show how GradeCalculator is supposed to work.
// If a test fails, fix the code in src/GradeCalc, not the test.

using GradeCalc;

namespace GradeCalc.Tests;

public class GradeCalculatorTests
{
    // ---------- Average ----------

    [Fact]
    public void Average_KeepsTheDecimalPart()
    {
        double result = GradeCalculator.Average(new List<int> { 85, 80 });

        Assert.Equal(82.5, result, precision: 2);
    }

    [Fact]
    public void Average_WholeNumberResult()
    {
        double result = GradeCalculator.Average(new List<int> { 70, 80, 90 });

        Assert.Equal(80, result, precision: 2);
    }

    [Fact]
    public void Average_EmptyList_ReturnsZero()
    {
        double result = GradeCalculator.Average(new List<int>());

        Assert.Equal(0, result, precision: 2);
    }

    // ---------- ToLetter ----------

    [Theory]
    [InlineData(95, "A")]
    [InlineData(90, "A")]
    [InlineData(89.9, "B")]
    [InlineData(80, "B")]
    [InlineData(75, "C")]
    [InlineData(65, "D")]
    [InlineData(59.9, "F")]
    public void ToLetter_UsesTheCourseScale(double percent, string expected)
    {
        string result = GradeCalculator.ToLetter(percent);

        Assert.Equal(expected, result);
    }

    // ---------- ApplyLatePenalty ----------

    [Fact]
    public void ApplyLatePenalty_OnTime_NoChange()
    {
        double result = GradeCalculator.ApplyLatePenalty(80, 0);

        Assert.Equal(80, result, precision: 2);
    }

    [Fact]
    public void ApplyLatePenalty_TwoDaysLate_Minus20()
    {
        double result = GradeCalculator.ApplyLatePenalty(80, 2);

        Assert.Equal(60, result, precision: 2);
    }

    [Fact]
    public void ApplyLatePenalty_NeverGoesBelowZero()
    {
        double result = GradeCalculator.ApplyLatePenalty(25, 3);

        Assert.Equal(0, result, precision: 2);
    }

    // ---------- IsPassing ----------

    [Theory]
    [InlineData(60, true)]
    [InlineData(59.9, false)]
    public void IsPassing_SixtyIsThePassMark(double percent, bool expected)
    {
        bool result = GradeCalculator.IsPassing(percent);

        Assert.Equal(expected, result);
    }
}
